CREATE OR REPLACE FUNCTION public.apply_search_meter(p_user_id uuid, p_credit_delta integer, p_daily_delta integer, p_description text, p_gate boolean DEFAULT true, p_daily_cap integer DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_credits integer; v_daily integer; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'apply_search_meter denied'; END IF; SELECT COALESCE(search_credits_remaining,0), COALESCE(daily_searches_used,0) INTO v_credits,v_daily FROM public.subscriptions WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('applied',false,'reason','no_subscription'); END IF; IF p_gate AND COALESCE(p_credit_delta,0)<0 AND v_credits+p_credit_delta<0 THEN RETURN jsonb_build_object('applied',false,'reason','insufficient','credits',v_credits,'daily',v_daily); END IF; IF p_daily_cap IS NOT NULL AND COALESCE(p_daily_delta,0)>0 AND v_daily+p_daily_delta>p_daily_cap THEN RETURN jsonb_build_object('applied',false,'reason','daily_cap','credits',v_credits,'daily',v_daily); END IF; v_credits:=GREATEST(0,v_credits+COALESCE(p_credit_delta,0)); v_daily:=GREATEST(0,v_daily+COALESCE(p_daily_delta,0)); UPDATE public.subscriptions SET search_credits_remaining=v_credits,daily_searches_used=v_daily WHERE user_id=p_user_id; IF COALESCE(p_credit_delta,0)<>0 THEN INSERT INTO public.search_transactions(user_id,type,amount,balance_after,description) VALUES(p_user_id,CASE WHEN p_credit_delta<0 THEN 'usage' ELSE 'refund' END,p_credit_delta,v_credits,left(COALESCE(p_description,''),500)); END IF; RETURN jsonb_build_object('applied',true,'credits',v_credits,'daily',v_daily); END; $$; REVOKE ALL ON FUNCTION public.apply_search_meter(uuid,integer,integer,text,boolean,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_search_meter(uuid,integer,integer,text,boolean,integer) TO service_role; COMMENT ON FUNCTION public.apply_search_meter(uuid,integer,integer,text,boolean,integer) IS 'Atomic app credit and daily-search meter; service callers only. Used identically by app, API and MCP actions.'; NOTIFY pgrst, 'reload schema';